import React from "react";
import { Container } from "react-bootstrap";
import { Header, ProjectCard } from "../../components";
import usePortfolioData from "../../hooks/usePortfolioData";
import styles from "./Projects.module.css";

const Projects = () => {
  const { projects: projectsData, loading } = usePortfolioData();
  const colorSequence = ["yellow", "purple", "cyan"];

  if (loading) return null; // Or a specific loader if desired

  return (
    <div className={styles.container}>
      <header className={styles.headerContainer}>
        <h1 className={styles.headerTitle}>Projects</h1>
      </header>

      <div className={styles.projectsGrid}>
        {projectsData.map((obj, index) => {
          const colorVariant = colorSequence[index % colorSequence.length];
          return (
            <ProjectCard
              key={index}
              title={obj.title}
              content={obj.content}
              gitHubUrl={obj.gitHubUrl}
              liveUrl={obj.liveUrl}
              techStack={obj.techStack}
              colorVariant={colorVariant}
            />
          );
        })}
      </div>
    </div>
  );
};

export default Projects;
